// Generates the markdown documents of handoff/NEW_INFORMATION_V7 from results/v7_results.json.
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const HERE = dirname(fileURLToPath(import.meta.url)); const REPO = join(HERE, '..', '..', '..'); const ROOT = join(REPO, 'research', 'new_information_v7'); const R = JSON.parse(readFileSync(join(ROOT, 'results', 'v7_results.json'), 'utf8')); const DEFN = R.finalist_definitions; const OUT = join(REPO, 'handoff', 'NEW_INFORMATION_V7'); mkdirSync(OUT, { recursive: true });
const f = (x, d = 3) => (x == null ? '—' : typeof x === 'number' ? (Number.isInteger(x) ? String(x) : x.toFixed(d)) : String(x)); const ci = (c) => (c ? `[${f(c[0])}, ${f(c[1])}]` : '—'); const pc = (x) => (x == null ? '—' : `${(x * 100).toFixed(1)} %`); const ts = (t) => (t ? new Date(t * 1000).toISOString().slice(0, 16) : '—'); const S2 = ['DEV', 'HOLD']; const POPS = ['CONTROL', 'S3']; const W = (name, md) => writeFileSync(join(OUT, name), md);
const CANDS = DEFN.candidates; const DEC = R.decisions; const HC = R.HOLD.candidates.CONTROL.CONTROL; const DC = R.DEV.candidates.CONTROL.CONTROL; const BEST = DEC.best_candidate; const HB = R.HOLD.candidates.CONTROL[BEST]; const DB = R.DEV.candidates.CONTROL[BEST]; const Q = R.meta.data_quality; const P = R.meta.parity;
const STH = '| Population | Split | State | N | Share | Win | Exp (R) | PF | Wrong-direction | Bad-entry | MFE open / MAE (R) | 95 % CI |\n|---|---|---|---|---|---|---|---|---|---|---|---|';
const stRows = (key) => POPS.flatMap((pop) => S2.flatMap((S) => { const T = R[S].tables[pop]; const states = T.states[key]; return [`| ${pop} | ${S} | **base** | ${T.base.n} | 100 % | ${pc(T.base.win_rate)} | ${f(T.base.expectancy_r)} | ${f(T.base.pf, 2)} | ${pc(T.base.wrong_direction_rate)} | ${pc(T.base.bad_entry_rate)} | ${f(T.base.mfe_open_r, 2)} / ${f(T.base.mae_r, 2)} | ${ci(T.base.ci95_r)} |`, ...Object.entries(states).map(([k, v]) => `| ${pop} | ${S} | ${k} | ${v.n}${v.n < 30 ? ' (INSUFFICIENT)' : ''} | ${pc(v.n / T.base.n)} | ${pc(v.win_rate)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.wrong_direction_rate)} | ${pc(v.bad_entry_rate)} | ${f(v.mfe_open_r, 2)} / ${f(v.mae_r, 2)} | ${ci(v.ci95_r)} |`)]; })).join('\n');
const INCH = '| Split | Population | Candidate | Trades | WAIT share | NA share | Exp (R) | Δ exp | PF | DD (R) | Wrong-direction (trade) | Δ WD | Event WD | Bad-entry | Capture | Incremental |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const incRow = (S, pop, k, v) => `| ${S} | ${pop} | ${k} | ${v.n} | ${pc(v.wait_share)} | ${pc(v.na_share)} | ${f(v.expectancy_r)} | ${f(v.improvement_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${pc(v.wrong_direction_rate)} | ${f(v.wd_change)} | ${pc(v.event_wd)} | ${pc(v.bad_entry_rate)} | ${pc(v.capture)} | ${v.incremental ? 'YES' : 'no'} |`;
const CANDH = '| Candidate | Signals in → kept (WAIT) | NA | Trades | Win | Avg win / loss (R) | Exp (R) | PF | DD (R) | Trade 95 % CI | Block 95 % CI | Stress | Drift | Quarters > 0 | WD trade / events | Bad-entry | Capture | Blocked events |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const candRow = (v, name) => (v.n ? `| ${name} | ${v.signals_in} → ${v.signals_kept} (${pc(v.wait_share)}) | ${pc(v.na_share)} | ${v.n} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${ci(v.block_ci95_r)} | ${f(v.stress?.expectancy_r)} | ${f(v.drift?.expectancy_r)} | ${pc(v.quarters_positive_share)} | ${pc(v.wrong_direction_rate)} / ${pc(v.move_capture.wrong_direction_rate)} | ${pc(v.bad_entry_rate)} | ${pc(v.move_capture.capture_rate)} | ${pc(v.blocked_events_share)} |` : `| ${name} | ${v.signals_in} → ${v.signals_kept} | — | 0 | | | | | | | | | | | | | 0 | |`);
const candTable = (pop, S) => `${CANDH}\n${candRow(R[S].candidates[pop].CONTROL, 'CONTROL (no V7 layer)')}\n${CANDS.map((k) => candRow(R[S].candidates[pop][k], k)).join('\n')}`;
const srcOf = (k) => (k === 'N9 COMBINATION' ? DEFN.combination.components.join(' + ') : R.meta.candidates[k].source);

// ---------- control / provenance / availability ----------
W('V7_CONTROL_BASELINE.md', readFileSync(join(ROOT, 'V7_CONTROL_BASELINE.md'), 'utf8') + `\n## Reproduction (asserted by the study)\n| Split | Population | n | Exp (R) | PF | DD (R) | WD trade | WD events | Capture |\n|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => POPS.map((pop) => { const v = R[S].candidates[pop].CONTROL; return `| ${S} | ${pop} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 2)} | ${pc(v.wrong_direction_rate)} | ${pc(v.move_capture.wrong_direction_rate)} | ${pc(v.move_capture.capture_rate)} |`; })).join('\n')}\n\ncontrol_reproduces_v6_dev = ${R.meta.controls.control_reproduces_v6_dev}; control_reproduces_v6_hold = ${R.meta.controls.control_reproduces_v6_hold}.\n`);
for (const fn of ['V7_PREREGISTRATION.md', 'V7_PREREGISTRATION.sha256', 'V7_CONTROL_BASELINE.sha256']) copyFileSync(join(ROOT, fn), join(OUT, fn));
W('DATA_PROVENANCE.md', `# DATA PROVENANCE (DATA SOURCE → RAW INFORMATION → FEATURE → DECISION-TIME AVAILABILITY)\n\n| Source | Raw information | Capture | Range in file | Feature(s) | Decision-time rule | Hash |\n|---|---|---|---|---|---|---|\n| Exness MT5 XAGUSDm (silver CFD) 5m / 15m | OHLC, tick volume, spread points per bar, broker server clock | read-only \`copy_rates\` by the Edge Lab (2026-09-30) and Stage 11B (2026-09-26); no query issued in V7 | 5m ${ts(Q.XAG5.first)} → ${ts(Q.XAG5.last)}; 15m ${ts(Q.XAG15.first)} → | silver_mom6, silver_act | 5m bar with the gold bar's open time (complete at the same instant); stale > 10 min → NA | ${R.meta.series_hashes.XAGUSDm.slice(0, 16)}… |\n| Exness MT5 DXYm (US dollar index CFD) 5m / 15m | OHLC, tick volume, spread | as above | 5m ${ts(Q.DXY5.first)} → ${ts(Q.DXY5.last)}; 15m ${ts(Q.DXY15.first)} → | dxy_mom6, dxy_range_mult | 5m same-open bar; before 2025-05-27 the last complete 15m bar (open ≤ t − 15 min); stale → NA | ${R.meta.series_hashes.DXYm.slice(0, 16)}… |\n| Exness MT5 USTECm (Nasdaq-100 CFD) 15m | OHLC, tick volume, spread | as above | ${ts(Q.UST15.first)} → ${ts(Q.UST15.last)} | ustec_mom2 | last complete 15m bar (open + 900 ≤ t); stale > 30 min → NA | ${R.meta.series_hashes.USTECm.slice(0, 16)}… |\n| Official USD release schedule | release timestamps (Federal Reserve, BLS, BEA pages; DST-checked); NO values / consensus | built 2026-09-26 from primary sources | ${R.meta.news_events_in_range} releases in range | release_reaction (sign of the first completed XAUUSD 5m bar after the release), approaching (≤ 30 min) | schedule known in advance; the reaction bar must be complete | ${R.meta.series_hashes.news.slice(0, 16)}… |\n| Exness MT5 XAUUSDm spread points | per-bar spread | existing bar file | whole range | spread_rank (trailing 288), spread_med_ratio | decision bar only | (control input) |\n| Live shadow observer records | LIVE-read XAGUSDm / DXYm / USTECm last 15m close, 96-bar z-score, 15m return per 5m decision | src/shadow observer, FORWARD_LIVE + BACKFILL provenance, 2026-09-25 → 2026-10-01 | ${P.records} records | parity only | — | read-only |\n\nFrozen hashes of every input: results/control_inputs.sha256 (38 lines). Tick volume is MT5 tick count (number of quote updates) of a CFD, never exchange volume.\n`);
W('DATA_AVAILABILITY.md', `# DATA AVAILABILITY (determined before any predictive test)\n\n| Family | Data | Available? | Real-time | Historical | Delay | Broker/exchange | Replayable | Forward-reproducible | MCP access | Decision |\n|---|---|---|---|---|---|---|---|---|---|---|\n| A real activity / volume | MT5 tick volume (XAUUSDm, XAGUSDm, DXYm, USTECm) | YES (proxy) | yes (per bar) | yes | none beyond bar completion | broker (Exness CFD quote-update count) | yes | yes | yes (existing bridge) | TEST as activity proxy; never "exchange volume" |\n| A real activity / volume | COMEX GC futures volume | NO | — | — | — | exchange | — | — | no feed | UNAVAILABLE |\n| B order flow / depth | MT5 market book (DOM) | live only, not captured | yes | NO | — | broker-synthetic CFD depth | no | unknown | technically via MT5 | FORWARD_ONLY_CANDIDATE |\n| C/F cross-asset silver | XAGUSDm 5m/15m | YES | yes | yes (5m from 2025-05-02) | bar completion | broker | yes | yes | yes | TEST |\n| D USD context | DXYm 5m/15m | YES | yes | 5m from 2025-05-27, 15m from 2022 | bar completion | broker CFD index | yes | yes | yes | TEST (15m fallback early DEV) |\n| E yields / Treasury | US10Y or bond CFD | NO instrument captured | — | — | — | — | — | — | not verified | UNAVAILABLE / DATA_UNVERIFIED |\n| G related markets | USTECm 15m | YES | yes | yes | bar completion | broker CFD | yes | yes | yes | TEST |\n| H macro calendar | official release timestamps | YES (times only) | schedule in advance | yes | — | official sources | yes | yes | News V2 calendar | TEST (timing + realized reaction); SURPRISE unavailable (no consensus/actual values) |\n| I news sentiment | headline / sentiment feed | NO | — | — | — | — | — | — | no feed | UNAVAILABLE (no fabrication) |\n| J session microstructure | opening-range behaviour | derived from XAUUSD price (not new data) | — | — | — | — | — | — | — | NOT NEW DATA; not tested as a candidate |\n| K liquidity / depth | as B | live only | — | NO | — | broker | no | — | — | FORWARD_ONLY_CANDIDATE |\n| L broker execution state | XAUUSDm spread points per bar; no latency/slippage logs | spread YES; latency NO | yes | yes | — | broker | yes | yes | yes | TEST spread state (ALLOW/RESTRICT/BLOCK); latency UNAVAILABLE |\n\nHistorical and live comparability was verified for the three cross-asset series with the live shadow observer records (LIVE_REPLAY_PARITY.md). No candidate was built on data without a verifiable historical series.\n`);
W('DATA_TIMESTAMP_INTEGRITY.md', `# DATA TIMESTAMP INTEGRITY\n\n| Rule | Implementation | Verification |\n|---|---|---|\n| Clock | all bar series on the Exness server clock (seconds UTC, open time) — same clock as XAUUSDm | 5m XAGUSDm bars share the gold bar open times for ${pc(1 - 182 / 99990)} of gold bars; DXYm 95.5 % (series starts 2025-05-27) |\n| Completion | a bar with open T and timeframe tf is complete at T + tf; usable at a decision tClose only if T + tf ≤ tClose | \`lastCompleteIndex\` (binary search on open times); study control: no feature bar closes after the decision (${R.meta.controls.timestamp_rule_no_future_bar}) |\n| Staleness | latest complete bar older than 2 × tf → NA (pass-through, counted) | NA shares per candidate: ${Object.entries(R.meta.na_rates).map(([k, v]) => `${k} ${pc(v)}`).join('; ')} |\n| Scheduled releases | published schedule known in advance; the reaction feature needs the first post-release bar to be complete | release_reaction uses bar j with open ≥ release and close ≤ decision |\n| No revised values | no economic values are used at all (timestamps only) | — |\n| Prefix invariance | every cross-asset feature recomputed on series truncated at the decision time | ${R.meta.controls.prefix_tested} signals, identical: ${R.meta.controls.cross_prefix_invariance} |\n| Feed-lag sensitivity | each finalist re-evaluated with one extra bar of delay | ${Object.entries(R.delay).map(([k, v]) => `${k}: Δ ${f(v.delta)}${v.sign_flip ? ' SIGN FLIP' : ''}`).join('; ')} |\n\nTIMESTAMP_INTEGRITY = ${DEC.timestamp_integrity}: the look-ahead rules pass everywhere; the aggregate is FAIL because the best candidate (silver confirmation) flips sign under a one-bar feed lag (+0.021 → −0.007 R), i.e. its value depends on using the silver bar the instant it completes.\n`);
W('DATA_QUALITY.md', `# DATA QUALITY (deterministic report per series; PASS = no duplicates, monotone, valid OHLC geometry, no return outlier > 10 × p99.9)\n\n| Series | Bars | In range | First | Last | Duplicates | Non-monotonic | Bad geometry | Zero-range bars | Intraday gaps > 1 step | Return outliers | Spread median (pts) | PASS |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${Object.entries(Q).map(([k, q]) => `| ${k} | ${q.bars} | ${q.in_range} | ${ts(q.first)} | ${ts(q.last)} | ${q.duplicates} | ${q.non_monotonic} | ${q.bad_geometry} | ${q.zero_range} | ${q.intraday_gaps} | ${q.return_outliers_gt_10x_p999} | ${q.spread_pts_median} | ${q.pass ? 'PASS' : 'FAIL'} |`).join('\n')}\n\nRobustness behaviour (tests/new_information_v7.test.js): missing bars → NA; stale bars → NA; duplicates / non-monotonic / bad geometry → quality FAIL; delayed data → one-bar-lag sensitivity; outliers → counted; reconnect / feed interruption → the feature simply becomes NA until a complete bar is available; no value is ever substituted from the future. DATA_QUALITY = ${DEC.data_quality}.\n`);
W('DATA_COST_AND_PRACTICALITY.md', `# DATA COST AND PRACTICALITY\n\n| Source | Subscription cost | API limits | Latency | Reliability | Historical availability | Licensing | Implementation complexity | Maintenance burden |\n|---|---|---|---|---|---|---|---|---|\n| Exness MT5 XAGUSDm / DXYm / USTECm bars | none beyond the existing account | MT5 terminal copy_rates, local; the shadow observer already reads three symbols per 5m cycle | bar completion (0 s) + reader round-trip (< 1 s) | broker feed; stale/closed-market handling needed (278 of 684 live records were STALE on weekends/holidays) | 5m ≈ 16 months (XAG), 16 months (DXY from 2025-05-27); 15m from 2022 | broker terms (personal use) | low: add symbols to the existing read-only reader; freshness rule already implemented in src/shadow/core.js | low (symbol visibility in Market Watch; server-time alignment) |\n| Official release schedule | none | none (static file rebuilt monthly) | known in advance | high | 2022 → | public | low | monthly refresh |\n| Broker spread per bar | none | none | 0 | high | whole range | — | none | none |\n| Order book / depth (forward only) | none (MT5 DOM) | per-tick | ms | broker-synthetic for CFDs | NONE | — | medium | high (tick storage) |\n| Exchange volume, yields, sentiment | paid feeds | vendor | vendor | — | not in environment | vendor | high | high |\n\nPracticality verdict: the only sources with incremental value (silver bars) are free, already read live by the shadow observer, and replayable — the cheapest possible new data. Their statistical value (+0.085 R HOLD, CI through zero, sign-flipping under one bar of lag) does not justify an implementation decision on its own; it justifies a pre-registered forward measurement, which the shadow observer already performs for silver (SC1_SILVER_LEAD_v1).\n`);

// ---------- family documents ----------
const famDoc = (file, title, keys, reading) => W(file, `# ${title}\n\n${keys.map((k) => `## ${k}\n${STH}\n${stRows(k)}\n`).join('\n')}\n## Reading\n${reading}\n`);
const hs = R.HOLD.tables.CONTROL.states, ds = R.DEV.tables.CONTROL.states;
famDoc('REAL_ACTIVITY_VOLUME.md', 'A. REAL MARKET ACTIVITY / VOLUME (what is available: MT5 tick volume of CFDs — a broker quote-update count, NOT exchange or futures volume)', ['silver_act', 'activity_divergence'], `Classification: no exchange volume, no futures volume, no broker traded volume — only tick volume (quote updates). Silver tick activity on HOLD: LOW ${f(hs.silver_act.LOW.expectancy_r)} R / HIGH ${f(hs.silver_act.HIGH.expectancy_r)} R vs NORMAL ${f(hs.silver_act.NORMAL.expectancy_r)} R; on DEV LOW was the worst state (${f(ds.silver_act.LOW.expectancy_r)} R, wrong direction ${pc(ds.silver_act.LOW.wrong_direction_rate)}) and HIGH the best — the ordering did not persist. Cross-asset activity confirmation (BOTH_HIGH) is positive on both splits (${f(ds.activity_divergence.BOTH_HIGH.expectancy_r)} / ${f(hs.activity_divergence.BOTH_HIGH.expectancy_r)} R) with ordinary wrong-direction; activity divergence (GOLD_ONLY) occurs in ${hs.activity_divergence.GOLD_ONLY?.n ?? 0} HOLD signals — too rare to test (N6 waits on 0.1 %). Verdict: activity information does not reduce wrong-direction trades; no activity rule qualifies.`);
famDoc('SILVER_CONTEXT.md', 'F. SILVER / PRECIOUS-METAL CONTEXT (XAGUSDm 5m, same-open bar; 6-bar momentum in silver ATR relative to the gold signal)', ['silver_mom6'], `This is the one new source with incremental value on both splits. Gold signals whose direction silver has NOT confirmed over the last 30 minutes are worse: OPPOSES_STRONG ${f(ds.silver_mom6.OPPOSES_STRONG.expectancy_r)} R (DEV, wrong direction ${pc(ds.silver_mom6.OPPOSES_STRONG.wrong_direction_rate)}) / ${f(hs.silver_mom6.OPPOSES_STRONG.expectancy_r)} R (HOLD, ${pc(hs.silver_mom6.OPPOSES_STRONG.wrong_direction_rate)}) versus AGREES_STRONG ${f(ds.silver_mom6.AGREES_STRONG.expectancy_r)} / ${f(hs.silver_mom6.AGREES_STRONG.expectancy_r)} R. Requiring strong agreement (N2, ≥ 0.75 silver ATR) waits on ${pc(HB.wait_share)} of signals and moves CONTROL from ${f(HC.expectancy_r)} to ${f(HB.expectancy_r)} R on HOLD (DEV ${f(DC.expectancy_r)} → ${f(DB.expectancy_r)} R) with wrong-direction ${pc(HC.wrong_direction_rate)} → ${pc(HB.wrong_direction_rate)} (DEV ${pc(DC.wrong_direction_rate)} → ${pc(DB.wrong_direction_rate)}). Limits: PF ${f(HB.pf, 2)}; CI ${ci(HB.ci95_r)}; stress ${f(HB.stress.expectancy_r)} R; neighbourhood SENSITIVE (0.3 → −0.016, 0.5 → +0.014, 0.75 → +0.021 R); SELL-driven on HOLD (SELL +0.100 n 465 / BUY −0.074 n 389) while DEV was side-neutral; positive in one of three HOLD quarters; sign flips with one bar of feed lag (+0.021 → −0.007 R); no effect on the S3 stream (−0.034 → −0.029 R). Redundancy: phi with the V6 gold-momentum flag −0.48 (strongly related to gold's own momentum, as expected for two metals moving together), < 0.2 with HTF, regime, session, shock. Verdict: genuine new information with a small, fragile, DEV-and-HOLD-consistent effect — INCONCLUSIVE, not an edge; the first new-data lead of the chain.`);
famDoc('USD_CONTEXT.md', 'D. USD / DOLLAR CONTEXT (DXYm 5m 6-bar momentum in DXY ATR relative to the gold signal; 15m fallback before 2025-05-27; dollar shock = range ≥ 2.5 ATR within 3 bars)', ['dxy_mom6', 'dxy_source', 'dxy_shock'], `The Edge Lab G2 observation (gold moving WITH the dollar fails) did not reproduce: on HOLD, gold signals with the dollar moving strongly in the same direction (WITH_STRONG) are ${f(hs.dxy_mom6.WITH_STRONG.expectancy_r)} R and those with the dollar against them (AGAINST_STRONG) ${f(hs.dxy_mom6.AGAINST_STRONG.expectancy_r)} R; on DEV the ordering was reversed (${f(ds.dxy_mom6.WITH_STRONG.expectancy_r)} vs ${f(ds.dxy_mom6.AGAINST_STRONG.expectancy_r)} R). Wrong-direction is 29–35 % in every dollar state. Waiting on dollar-with signals (N3) is −0.062 R on both splits. Dollar shock (N4, ${pc(hs.dxy_shock.SHOCK.n / R.HOLD.tables.CONTROL.base.n)} of signals) was positive on DEV and flat on HOLD, with lower wrong-direction on both (${pc(ds.dxy_shock.SHOCK.wrong_direction_rate)} / ${pc(hs.dxy_shock.SHOCK.wrong_direction_rate)}) — a dollar shock is when gold moves, not a reason to wait. The 5m/15m fallback (${pc(ds.dxy_source['15m'].n / R.DEV.tables.CONTROL.base.n)} of DEV signals) behaves like the 5m data. Verdict: the dollar carries no incremental directional information for these entries (consistent with Stage 11B's −0.56 contemporaneous correlation but no lead).`);
W('YIELD_CONTEXT.md', `# E. TREASURY / YIELD CONTEXT\n\nNo Treasury or yield instrument exists in the captured data, and none was fetched during V7 (no MT5 query was issued; the running REAL watcher and bridge were not touched). Whether the broker lists a bond or yield CFD was not verified → DATA_UNVERIFIED. No yield feature was computed, no yield label was fabricated, and no conclusion is drawn about gold/yield relationships.\n\nIf a future stage captures a yield series (read-only, same broker clock or a timestamped public source), the V7 framework applies unchanged: bar complete ≤ decision, NA pass-through, one-bar-delay sensitivity, prefix invariance, parity against live records, one source at a time.\n`);
famDoc('RELATED_MARKETS.md', 'G. MAJOR RELATED MARKET CONTEXT (USTECm 15m, last complete bar, 2-bar momentum in USTEC ATR; "risk-off favours gold BUY" hypothesis)', ['ustec_mom2'], `The risk-proxy hypothesis fails in both directions: on HOLD, gold signals with the Nasdaq moving strongly WITH them (risk-on + gold BUY, or risk-off + gold SELL) are the best state (${f(hs.ustec_mom2.RISK_WITH_STRONG.expectancy_r)} R, wrong direction ${pc(hs.ustec_mom2.RISK_WITH_STRONG.wrong_direction_rate)}) and RISK_AGAINST_STRONG the worst (${f(hs.ustec_mom2.RISK_AGAINST_STRONG.expectancy_r)} R); on DEV both strong states were ≈ −0.06 to −0.09 R. Waiting on risk-with signals (N5) is the worst candidate (HOLD ${f(R.HOLD.candidates.CONTROL['N5 USTEC_RISK'].expectancy_r)} R, wrong direction UP). FLAT Nasdaq is the worst state on HOLD (−0.180 R). No arbitrary correlation mining was done beyond the one pre-registered rule. Verdict: no incremental information; rejected.`);
famDoc('CROSS_ASSET_CONTEXT.md', 'C. CROSS-ASSET / INTERMARKET CONTEXT (summary across silver, dollar index and Nasdaq; lead/lag vs contemporaneous)', ['silver_mom6', 'dxy_mom6', 'ustec_mom2'], `Lead/lag: Stage 11B (15m, 2022–2026) and the Edge Lab (5m) found no exploitable lead of silver, DXY or USTEC over gold (5m lead correlations +0.02 / −0.02). V7 therefore tests CONTEMPORANEOUS confirmation at the decision bar — information that exists before the gold decision because the other instrument's bar completes at the same instant on the same clock. Direction agreement with silver is the only relationship with consistent sign and economics across splits (SILVER_CONTEXT.md); dollar and Nasdaq agreement reverse between splits (USD_CONTEXT.md, RELATED_MARKETS.md). Synchronised-bar hindsight was excluded structurally (bar close ≤ decision; prefix invariance; one-bar-delay test).`);
famDoc('MACRO_CONTEXT.md', 'H. MACRO CALENDAR STATE (official release timestamps; approaching ≤ 30 min; post-release reaction = sign of the first completed XAUUSD 5m bar after the release; 120-min window; release VALUES not available → no surprise feature)', ['macro'], `Signals inside a release window are rare (${pc((hs.macro.POST_RELEASE_WITH_REACTION.n + hs.macro.POST_RELEASE_AGAINST_REACTION.n + hs.macro.APPROACHING_30M.n) / R.HOLD.tables.CONTROL.base.n)} of HOLD signals) and, as in V6, positive on both splits in every sub-state except DEV against-reaction (${f(ds.macro.POST_RELEASE_AGAINST_REACTION.expectancy_r)} R, n ${ds.macro.POST_RELEASE_AGAINST_REACTION.n}) — which became ${f(hs.macro.POST_RELEASE_AGAINST_REACTION.expectancy_r)} R on HOLD (n ${hs.macro.POST_RELEASE_AGAINST_REACTION.n}). The pre-registered rule (wait against the reaction and in the 30 min before a release) therefore removed good trades on HOLD (N7 −0.055 vs −0.064 R, i.e. no gain). Event surprise could not be researched: no consensus or actual values exist in the environment and none were fabricated. Verdict: the realized post-release reaction is not new raw data (it is XAUUSD price) and does not add directional value; release timing remains a safety variable owned by News V2.`);
W('NEWS_SENTIMENT.md', `# I. NEWS / SENTIMENT\n\nNo timestamped headline or sentiment feed exists in the environment. Nothing was scraped, no generic AI sentiment was generated, and no sentiment label was fabricated. Family I is UNAVAILABLE / DATA_UNVERIFIED and contributes nothing to the edge conclusions. If a licensed, timestamped feed is added later, the V7 framework applies (publication timestamp ≤ decision; prefix invariance; one-source test).\n`);
W('SESSION_MICROSTRUCTURE.md', `# J. SESSION MICROSTRUCTURE\n\nV6 tested session, overlap, session-open and US-data windows (no persistent value). Opening-range behaviour, session-transition pressure and pre/post-overlap behaviour are functions of the XAUUSD price series already in the V6 feature set; they are NOT new data and were not promoted to V7 candidates (the directive requires proof that the data is new). The only microstructure information that IS new in V7 is cross-asset: silver's contemporaneous bar (SILVER_CONTEXT.md). Stage 11B had already tested London / NY opening-range breaks on 15m data from 2022 (S1L/S1N: fail).\n`);
W('ORDER_FLOW_DEPTH.md', `# B. ORDER FLOW / MARKET DEPTH\n\nStatus: FORWARD_ONLY_CANDIDATE. MT5 exposes a market book (\`market_book_get\`) for some Exness symbols live, but (a) no depth history exists in the environment, (b) CFD depth at a retail broker is broker-synthetic, not the global market, and (c) no bid/ask imbalance, delta or aggressive-flow series was ever captured. Nothing was fabricated; no historical edge is claimed. See FORWARD_ONLY_CANDIDATES.md for the measurement plan.\n`);
W('LIQUIDITY_DEPTH.md', `# K. LIQUIDITY / MARKET DEPTH\n\nSame status as order flow: FORWARD_ONLY_CANDIDATE. Liquidity concentration, withdrawal and spread/depth relationships need a depth history that does not exist here. The only liquidity-adjacent measure available historically is the broker spread per bar, which is treated as execution state (BROKER_EXECUTION_STATE.md), not as market depth. Broker depth would never be presented as global market depth.\n`);
famDoc('BROKER_EXECUTION_STATE.md', 'L. BROKER EXECUTION STATE (XAUUSDm spread points: trailing-288 percentile rank and ratio to the trailing median; ALLOW / RESTRICT / BLOCK, not a directional signal)', ['spread_state'], `Production signals occur almost entirely at the modal spread (${pc(hs.spread_state.LOW_P10.n / R.HOLD.tables.CONTROL.base.n)} of HOLD signals in the LOW_P10 state because the modal 160-point spread ranks at the bottom of its own trailing window). Expanded spread (≥ 1.5 × trailing median) covers ${pc(hs.spread_state['EXPANDED_1.5x'].n / R.HOLD.tables.CONTROL.base.n)} of HOLD signals and is strongly negative there (${f(hs.spread_state['EXPANDED_1.5x'].expectancy_r)} R, n ${hs.spread_state['EXPANDED_1.5x'].n}) and on DEV (${f(ds.spread_state['EXPANDED_1.5x'].expectancy_r)} R, n ${ds.spread_state['EXPANDED_1.5x'].n}) — with ordinary wrong-direction, i.e. the damage is execution cost, not direction. Blocking it (N8) changes HOLD expectancy by +0.009 R because so few signals are affected. Execution latency and slippage logs are not available. Verdict: a spread-expansion BLOCK is a sensible execution-state guard (production already has the 0.60 USD spread gate) but it is not an information edge.`);

// ---------- incremental / redundancy / ablation ----------
W('INCREMENTAL_INFORMATION.md', `# INCREMENTAL INFORMATION (CONTROL vs CONTROL + NEW SOURCE; sequential; control exit; NORMAL costs; incremental = N ≥ 200, ≥ +0.05 R and lower wrong-direction)\n\n${INCH}\n${S2.flatMap((S) => POPS.flatMap((pop) => Object.entries(R.incremental[S][pop]).map(([k, v]) => incRow(S, pop, k, v)))).join('\n')}\n\nSources with incremental value on both splits (CONTROL stream): ${DEC.families_with_incremental_value_both_splits.join(', ') || 'none'}; on one split: ${DEC.families_with_incremental_value_one_split.join(', ') || 'none'}. INFORMATION_INCREMENTAL_VALUE = ${DEC.information_incremental_value}.\n\n## Reading\nSilver confirmation (N2) and the combination (which reduces to N2 because N2's WAIT set contains N1's) are the first information sources in the V1–V7 chain to add ≥ 0.05 R with lower wrong-direction on BOTH splits (+0.066 R DEV, +0.085 R HOLD; wrong-direction −2.3 / −0.5 points). Silver opposition alone (N1) qualified on DEV and vanished on HOLD. No other source adds anything on either split. On the V4 S3 stream silver adds nothing (+0.005 R), so the effect is specific to the production entry population.\n`);
W('REDUNDANCY_ANALYSIS.md', `# REDUNDANCY ANALYSIS (phi between each new WAIT flag and the V6 flags on CONTROL signals; |phi| ≥ 0.5 = redundant)\n\n${S2.map((S) => { const rd = R[S].redundancy; return `## ${S}\nFlag rates: ${Object.entries(rd.rates).map(([k, v]) => `${k} ${pc(v)}`).join('; ')}.\n\n| Pair | phi |\n|---|---|\n${Object.entries(rd.phi).filter(([, v]) => v != null && Math.abs(v) >= 0.1).sort((a, b) => Math.abs(b[1]) - Math.abs(a[1])).map(([k, v]) => `| ${k} | ${f(v, 2)} |`).join('\n')}\n\nRedundant pairs: ${rd.redundant_pairs.length ? rd.redundant_pairs.join('; ') : 'none'}.\n`; }).join('\n')}\n## Reading\nThe silver flags are related to gold's own 6-bar momentum (phi −0.47 / −0.48: when gold momentum supports the signal, silver usually does too) but not redundant with it (|phi| < 0.5), and they are independent of HTF structure, regime, session, shock, news and tick activity (|phi| < 0.2). Dollar-with and silver flags share phi 0.16–0.17. The silver information is therefore partly a second reading of the metals complex's momentum and partly new; its incremental value over the V6 momentum rule (which had none) shows the new part matters.\n`);
W('ABLATION_RESULTS.md', `# ABLATION RESULTS (remove the new source from the best candidate)\n\n| Split | With source (${R.ablation.best}) | Without source (CONTROL) | Δ expectancy | Essential (|Δ| ≥ 0.05 R) |\n|---|---|---|---|---|\n| HOLD | n ${R.ablation.HOLD.with_source.n}, ${f(R.ablation.HOLD.with_source.expectancy_r)} R, WD ${pc(R.ablation.HOLD.with_source.wrong_direction_rate)}, capture ${pc(R.ablation.HOLD.with_source.capture)} | n ${R.ablation.HOLD.without_source.n}, ${f(R.ablation.HOLD.without_source.expectancy_r)} R, WD ${pc(R.ablation.HOLD.without_source.wrong_direction_rate)}, capture ${pc(R.ablation.HOLD.without_source.capture)} | ${f(R.ablation.HOLD.delta_expectancy)} | ${R.ablation.HOLD.essential ? 'YES' : 'no'} |\n| DEV | n ${R.ablation.DEV.with_source.n}, ${f(R.ablation.DEV.with_source.expectancy_r)} R, WD ${pc(R.ablation.DEV.with_source.wrong_direction_rate)} | n ${R.ablation.DEV.without_source.n}, ${f(R.ablation.DEV.without_source.expectancy_r)} R, WD ${pc(R.ablation.DEV.without_source.wrong_direction_rate)} | ${f(R.ablation.DEV.delta_expectancy)} | — |\n\nThe source is essential to the candidate (removing it returns CONTROL), and the combination N9 is identical to N2 (silver opposition's WAIT set is a subset of silver confirmation's), so no redundant complexity is retained: the entire V7 finding is one rule on one source.\n`);

// ---------- direction / wrong direction / missed moves / economics ----------
W('DIRECTIONAL_IMPACT.md', `# DIRECTIONAL IMPACT (does the new information improve BUY / SELL / WAIT decisions?)\n\n| Split | Candidate | WAIT share | Trades | Wrong-direction (trade) | Event wrong-direction | Bad-entry | Right-direction (≥ +1 R) | Exp (R) | BUY n / exp / WD | SELL n / exp / WD |\n|---|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates.CONTROL[k]; if (!v.n) return `| ${S} | ${k} | ${pc(v.wait_share)} | 0 | — | — | — | — | — | — | — |`; const b = v.by_side?.BUY, s = v.by_side?.SELL; return `| ${S} | ${k} | ${pc(v.wait_share)} | ${v.n} | ${pc(v.wrong_direction_rate)} | ${pc(v.move_capture.wrong_direction_rate)} | ${pc(v.bad_entry_rate)} | ${pc(v.right_direction_rate)} | ${f(v.expectancy_r)} | ${b ? `${b.n} / ${f(b.expectancy_r)} / ${pc(b.wrong_direction_rate)}` : '—'} | ${s ? `${s.n} / ${f(s.expectancy_r)} / ${pc(s.wrong_direction_rate)}` : '—'} |`; })).join('\n')}\n\n## Reading\nThe WAIT decisions of the silver confirmation remove trades with a wrong-direction rate of ≈ 31 % and keep trades at ${pc(HB.wrong_direction_rate)} (HOLD) — a 0.5-point improvement, 2.3 points on DEV. The improvement in expectancy (+0.085 R) comes less from fewer wrong trades than from the removed trades being the poorer right trades too (bad-entry ${pc(HC.bad_entry_rate)} → ${pc(HB.bad_entry_rate)}); on HOLD the whole gain sits on the SELL side. DIRECTIONAL_ACCURACY_IMPROVED = ${DEC.directional_accuracy_improved}.\n`);
W('WRONG_DIRECTION_ANALYSIS.md', `# WRONG-DIRECTION ANALYSIS (primary metric; V6 baseline reproduced exactly)\n\n| Measure | CONTROL DEV | CONTROL HOLD | Best V7 (${BEST}) DEV | Best V7 HOLD |\n|---|---|---|---|---|\n| Trade-level wrong direction | ${pc(DC.wrong_direction_rate)} | ${pc(HC.wrong_direction_rate)} | ${pc(DB.wrong_direction_rate)} | ${pc(HB.wrong_direction_rate)} |\n| Event-level wrong direction | ${pc(DC.move_capture.wrong_direction_rate)} | ${pc(HC.move_capture.wrong_direction_rate)} | ${pc(DB.move_capture.wrong_direction_rate)} | ${pc(HB.move_capture.wrong_direction_rate)} |\n| Bad entry (never +1 R) | ${pc(DC.bad_entry_rate)} | ${pc(HC.bad_entry_rate)} | ${pc(DB.bad_entry_rate)} | ${pc(HB.bad_entry_rate)} |\n| Trades | ${DC.n} | ${HC.n} | ${DB.n} | ${HB.n} |\n\n## Wrong-direction by new-information state (CONTROL stream, states with N ≥ 100)\n| Split | Feature | State | N | Wrong-direction | vs base |\n|---|---|---|---|---|---|\n${S2.flatMap((S) => Object.entries(R[S].tables.CONTROL.states).flatMap(([fam, st]) => Object.entries(st).filter(([, v]) => v.n >= 100).map(([k, v]) => `| ${S} | ${fam} | ${k} | ${v.n} | ${pc(v.wrong_direction_rate)} | ${f(v.wrong_direction_rate - R[S].tables.CONTROL.base.wrong_direction_rate)} |`))).join('\n')}\n\n## Reading\nThe ~30 % wrong-direction population is not materially reduced by any new source: the best state-level reductions on HOLD (silver AGREES ${pc(hs.silver_mom6.AGREES.wrong_direction_rate)}, Nasdaq RISK_WITH_STRONG ${pc(hs.ustec_mom2.RISK_WITH_STRONG.wrong_direction_rate)}, dollar shock ${pc(hs.dxy_shock.SHOCK.wrong_direction_rate)}) are 1–4 points, and the only candidate with consistent direction (silver confirmation) reduces the trade-level rate by 0.5 points on HOLD. The event-level rate falls to ${pc(HB.move_capture.wrong_direction_rate)} for the silver candidate only because it signals less often (capture ${pc(HB.move_capture.capture_rate)} vs ${pc(HC.move_capture.capture_rate)}).\n`);
W('MISSED_MOVE_ANALYSIS.md', `# MISSED-MOVE ANALYSIS (V4 move events; NO_SETUP / NO_TRIGGER unchanged by construction — V7 layers sit after the trigger; BLOCKED = events the unfiltered stream captured but the V7 layer waited out)\n\n| Split | Candidate | Events | Capture | Valid (≤ onset) | Late | Wrong direction | Already positioned | No signal | of which no setup/trigger | of which production gate | Blocked by V7 |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates.CONTROL[k]; const m = v.move_capture; return `| ${S} | ${k} | ${m.events} | ${pc(m.capture_rate)} | ${pc(m.valid_entry_rate)} | ${pc(m.late_entry_rate)} | ${pc(m.wrong_direction_rate)} | ${pc(m.already_positioned_rate)} | ${pc(m.no_signal_rate)} | ${pc(m.no_setup_or_trigger_rate)} | ${pc(m.gate_or_filter_rate)} | ${pc(v.blocked_events_share)} |`; })).join('\n')}\n\n## Reading\nSilver confirmation waits out ${pc(HB.blocked_events_share)} of HOLD move events that the production stream would have captured (capture ${pc(HC.move_capture.capture_rate)} → ${pc(HB.move_capture.capture_rate)}) while removing 7.6 points of event-level wrong direction: it trades fewer moves and fewer wrong moves in roughly equal measure. No new source reduces a failure class without enlarging the missed-opportunity class; none reduces NO_SETUP / NO_TRIGGER, which remains the dominant failure (32.5 %).\n`);
W('TRADE_ECONOMICS.md', `# TRADE ECONOMICS (V5 measures on the V7 candidates; HOLDOUT; control exit)\n\n| Candidate | Trades | Exp (R) | Reach +1 R | Reach +1.7 R | Stop reached | Open-path MFE (R) | MAE (R) | Give-back (R) | Win | Avg win / loss (R) | Risk USD mean | USD @0.01 |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return v.n ? `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${pc(v.stop_reach)} | ${f(v.mfe_open_r, 2)} | ${f(v.mae_r, 2)} | ${f(v.giveback_r, 2)} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.risk_usd_mean, 2)} | ${f(v.expectancy_usd, 2)} |` : `| ${k} | 0 | — | — | — | — | — | — | — | — | — | — | — |`; }).join('\n')}\n\n## Reading\nThe silver-confirmed population reaches +1 R in ${pc(HB.reach_1r)} of trades vs ${pc(HC.reach_1r)} and its stop in ${pc(HB.stop_reach)} vs ${pc(HC.stop_reach)}; give-back is unchanged (${f(HB.giveback_r, 2)} vs ${f(HC.giveback_r, 2)} R). The economics improve by 0.085 R per trade — still a PF of ${f(HB.pf, 2)}, negative under stress costs (${f(HB.stress.expectancy_r)} R) and a drawdown of ${f(HB.max_dd_r, 1)} R. TRADE_ECONOMICS_IMPROVED = ${DEC.trade_economics_improved}.\n`);

// ---------- candidates / results ----------
W('CANDIDATE_DEFINITIONS.md', `# CANDIDATE DEFINITIONS (≤ 8 + one pre-registered combination; every candidate = CONTROL entries + a WAIT rule from ONE new source; control exit; RR 1.70; lot 0.01)\n\n| Candidate | Source / provenance | Timestamp rule | Hypothesis / mechanism | Feature | WAIT when | Grid (DEV-selected value) | DEV result |\n|---|---|---|---|---|---|---|---|\n| N1 SILVER_OPPOSE | XAGUSDm 5m (Exness, same clock) | same-open bar complete at the decision | metals move together; a gold signal against silver's 30-min move is suspect | silver_mom6 | silver opposes ≥ thr | {0.5, 0.75, 1.0} → ${DEFN.finalists['N1 SILVER_OPPOSE'].value} | ${f(DEFN.finalists['N1 SILVER_OPPOSE'].dev_expectancy_r)} R, Δ ${f(DEFN.finalists['N1 SILVER_OPPOSE'].dev_improvement_r)} |\n| N2 SILVER_CONFIRM | XAGUSDm 5m | as above | strict version: require silver agreement | silver_mom6 | silver does NOT agree ≥ thr | {0.3, 0.5, 0.75} → ${DEFN.finalists['N2 SILVER_CONFIRM'].value} | ${f(DEFN.finalists['N2 SILVER_CONFIRM'].dev_expectancy_r)} R, Δ ${f(DEFN.finalists['N2 SILVER_CONFIRM'].dev_improvement_r)} |\n| N3 DXY_WITH | DXYm 5m (15m fallback) | same-open bar / last complete 15m | gold moves with the dollar fail (Edge Lab G2) | dxy_mom6 | dollar moves with the gold signal ≥ thr | {0.5, 0.75, 1.0} → ${DEFN.finalists['N3 DXY_WITH'].value} | ${f(DEFN.finalists['N3 DXY_WITH'].dev_expectancy_r)} R |\n| N4 DXY_SHOCK | DXYm | as above | dollar volatility shock = unstable context | dxy_range_mult | range ≥ k × DXY ATR within 3 bars | {2.0, 2.5, 3.0} → ${DEFN.finalists['N4 DXY_SHOCK'].value} | ${f(DEFN.finalists['N4 DXY_SHOCK'].dev_expectancy_r)} R |\n| N5 USTEC_RISK | USTECm 15m | last complete 15m bar | risk-off favours gold BUY | ustec_mom2 | Nasdaq moves with the gold signal ≥ thr | {0.5, 0.75, 1.0} → ${DEFN.finalists['N5 USTEC_RISK'].value} | ${f(DEFN.finalists['N5 USTEC_RISK'].dev_expectancy_r)} R |\n| N6 ACTIVITY_DIVERGENCE | XAGUSDm + XAUUSDm tick volume | same-open bars | gold-only activity without silver participation is unreliable | gold_act, silver_act | gold ≥ 1.5× and silver ≤ thr | {0.6, 0.7, 0.8} → ${DEFN.finalists['N6 ACTIVITY_DIVERGENCE'].value} | ${f(DEFN.finalists['N6 ACTIVITY_DIVERGENCE'].dev_expectancy_r)} R |\n| N7 MACRO_REACTION | official release timestamps + XAUUSD price (DERIVED) | schedule in advance; reaction bar complete | post-release reaction direction persists | release_reaction, approaching | signal opposes the reaction within the window, or release ≤ 30 min ahead | {60, 120, 180} → ${DEFN.finalists['N7 MACRO_REACTION'].value} | ${f(DEFN.finalists['N7 MACRO_REACTION'].dev_expectancy_r)} R |\n| N8 SPREAD_STATE | XAUUSDm broker spread (execution state) | decision bar | expanded spread predicts poor execution | spread_rank, spread_med_ratio | rank > p or ratio ≥ 1.5 | {0.85, 0.90, 0.95} → ${DEFN.finalists['N8 SPREAD_STATE'].value} | ${f(DEFN.finalists['N8 SPREAD_STATE'].dev_expectancy_r)} R |\n| N9 COMBINATION | ${DEFN.combination.components.join(' + ')} | — | ${DEFN.combination.rule} | — | any component waits | — | — |\n\nOne source at a time; the combination was allowed only because two sources had DEV incremental value, and it reduces to N2 (N1's WAIT set ⊂ N2's).\n`);
W('FROZEN_FINALISTS.md', `# FROZEN FINALISTS\n\n\`configs/finalists.json\` sha256 **${R.finalists_sha256}**, derived from DEV only, frozen before HOLDOUT was opened (results/dev_phase_console.txt → results/full_phase_console.txt).\n\n| Candidate | Source | Selected value | DEV N | DEV exp (R) | DEV Δ | DEV WD | WD lower | DEV incremental | WAIT share | NA share |\n|---|---|---|---|---|---|---|---|---|---|---|\n${CANDS.filter((k) => DEFN.finalists[k]).map((k) => { const v = DEFN.finalists[k]; return `| ${k} | ${v.source} | ${v.value} | ${v.dev_n} | ${f(v.dev_expectancy_r)} | ${f(v.dev_improvement_r)} | ${pc(v.dev_wd)} | ${v.dev_wd_lower ? 'yes' : 'no'} | ${v.dev_incremental ? 'YES' : 'no'} | ${pc(v.wait_share)} | ${pc(v.na_share)} |`; }).join('\n')}\n\nCombination: ${DEFN.combination.components.join(' + ') || 'none'} (${DEFN.combination.rule}).\n`);
W('DEVELOPMENT_RESULTS.md', `# DEVELOPMENT RESULTS (2025-05-07 → 2025-12-31; sequential; control exit; NORMAL costs)\n\n## CONTROL stream\n${candTable('CONTROL', 'DEV')}\n\n## S3 stream\n${candTable('S3', 'DEV')}\n`);
W('HOLDOUT_RESULTS.md', `# HOLDOUT RESULTS (2026-01-01 → 2026-09-29; opened once after configs/finalists.json was hashed; sequential; control exit; NORMAL costs)\n\n## CONTROL stream\n${candTable('CONTROL', 'HOLD')}\n\n## S3 stream\n${candTable('S3', 'HOLD')}\n\n## Gate decisions (V7_PREREGISTRATION.md §8; CONTROL stream)\n| Candidate | Status | Failed items |\n|---|---|---|\n${CANDS.map((k) => `| ${k} | ${DEC.candidates[k].status} | ${(DEC.candidates[k].reasons ?? []).join('; ') || '—'} |`).join('\n')}\n\nPassing: ${DEC.passing.length ? DEC.passing.join(', ') : 'none'}. Best by HOLDOUT expectancy with N ≥ 200: **${BEST}** (source ${srcOf(BEST)}): ${HB.n} trades, ${f(HB.expectancy_r)} R, PF ${f(HB.pf, 2)}, DD ${f(HB.max_dd_r, 1)} R, trade CI ${ci(HB.ci95_r)}, block CI ${ci(HB.block_ci95_r)}, 99 % CI ${ci(HB.ci99_r)}, wrong-direction ${pc(HB.wrong_direction_rate)} / ${pc(HB.move_capture.wrong_direction_rate)} vs CONTROL ${pc(HC.wrong_direction_rate)} / ${pc(HC.move_capture.wrong_direction_rate)}, capture ${pc(HB.move_capture.capture_rate)} vs ${pc(HC.move_capture.capture_rate)}, DEV ${f(DB.expectancy_r)} R. INFORMATION_INCREMENTAL_VALUE = ${DEC.information_incremental_value}; DIRECTIONAL_ACCURACY_IMPROVED = ${DEC.directional_accuracy_improved}; TRADE_ECONOMICS_IMPROVED = ${DEC.trade_economics_improved}; EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; DEMO_ELIGIBLE = ${DEC.demo_eligible}.\n`);
W('NORMAL_COST_RESULTS.md', `# NORMAL COST RESULTS (spread 0.24 + slippage 0.10 USD; DRIFT = next-open fill; HOLDOUT, CONTROL stream)\n\n| Candidate | Trades | Exp (R) | Exp (USD @0.01) | Cost USD/trade | PF | DD (R) | Drift exp (R) | Drift PF |\n|---|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return v.n ? `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.cost_usd, 2)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${f(v.drift.expectancy_r)} | ${f(v.drift.pf, 2)} |` : `| ${k} | 0 | — | — | — | — | — | — | — |`; }).join('\n')}\n`);
W('STRESS_COST_RESULTS.md', `# STRESS COST RESULTS (spread 0.60 + slippage 0.20 USD; CONTROL stream)\n\n| Split | Candidate | Trades | Normal exp (R) | Stress exp (R) | Stress PF | Degradation (R) |\n|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates.CONTROL[k]; return v.n ? `| ${S} | ${k} | ${v.stress.n} | ${f(v.expectancy_r)} | ${f(v.stress.expectancy_r)} | ${f(v.stress.pf, 2)} | ${f(v.stress.expectancy_r - v.expectancy_r)} |` : `| ${S} | ${k} | 0 | — | — | — | — |`; })).join('\n')}\n\nThe silver confirmation is +0.021 R at normal cost and −0.069 R at stress cost on HOLDOUT (−0.098 R on DEV): it works only before costs widen, which the pre-registration rejects.\n`);
W('WALK_FORWARD_RESULTS.md', `# WALK-FORWARD RESULTS (calendar quarters; sequential; control exit; CONTROL stream)\n\n${S2.map((S) => `## ${S}\n| Candidate | ${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).join(' | ')} | Quarters > 0 |\n|---|${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).map(() => '---|').join('')}---|\n${['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates.CONTROL[k]; if (!v.n) return `| ${k} | — | — |`; return `| ${k} | ${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).map((q) => { const x = v.walk_forward[q]; return x ? `n ${x.n}, ${f(x.expectancy_r)} R, PF ${f(x.pf, 2)}, DD ${f(x.max_dd_r, 0)}, WD ${pc(x.wrong_direction_rate)}, ${f(x.trades_per_session, 1)}/session` : '—'; }).join(' | ')} | ${pc(v.quarters_positive_share)} |`; }).join('\n')}\n`).join('\n')}\n## Reading\nSilver confirmation is positive in 2 of 3 DEV quarters and 1 of 3 HOLD quarters (2026Q2 +0.099 R; Q1 −0.025; Q3 −0.011) — better than CONTROL in every quarter but positive only where CONTROL itself was least negative. A period-independent edge is not shown.\n`);
W('UNCERTAINTY_ANALYSIS.md', `# UNCERTAINTY ANALYSIS (trade bootstrap 2,000 draws seed 20260930; session-block bootstrap seed 7; month-shuffle adverse sequencing 500 draws; HOLDOUT, CONTROL stream)\n\n| Candidate | N | Exp (R) | Trade 95 % CI | Trade 99 % CI | Block 95 % CI | Block 99 % CI | PF | Max loss streak | Adverse DD R p50 / p90 / p99 | Loss streak p50 / p90 | Neighbourhood |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return v.n ? `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${ci(v.ci95_r)} | ${ci(v.ci99_r)} | ${ci(v.block_ci95_r)} | ${ci(v.block_ci99_r)} | ${f(v.pf, 2)} | ${v.max_loss_streak} | ${v.adverse ? `${f(v.adverse.dd_r_p50, 1)} / ${f(v.adverse.dd_r_p90, 1)} / ${f(v.adverse.dd_r_p99, 1)}` : '—'} | ${v.adverse ? `${v.adverse.loss_streak_p50} / ${v.adverse.loss_streak_p90}` : '—'} | ${k === 'CONTROL' ? '—' : R.neighbourhoods[k]?.classification ?? '—'} |` : `| ${k} | 0 | — | — | — | — | — | — | — | — | — | — |`; }).join('\n')}\n\n## Parameter neighbourhoods (HOLD)\n${CANDS.filter((k) => R.neighbourhoods[k] && k !== 'N9 COMBINATION').map((k) => `**${k}** — ${R.neighbourhoods[k].classification}: ${Object.entries(R.neighbourhoods[k]).filter(([a]) => a !== 'classification').map(([a, v]) => `${a} → n ${v.n}, ${f(v.expectancy_r)} R, WD ${pc(v.wrong_direction_rate)}`).join('; ')}`).join('\n\n')}\n\n## Reading\nThe silver confirmation's 95 % CI ${ci(HB.ci95_r)} and 99 % CI ${ci(HB.ci99_r)} include zero; it was the best of 8 candidates × 3 grid values; its neighbourhood is SENSITIVE (the 0.3 threshold is negative). UNCERTAINTY_RESULT = INCONCLUSIVE. Every other candidate is NEGATIVE_CENTRE.\n`);
W('LIVE_REPLAY_PARITY.md', `# LIVE ↔ REPLAY PARITY (the first V-stage with a genuine live-vs-replay comparison for the new data)\n\nThe Stage 11C shadow observer has read XAGUSDm / DXYm / USTECm 15m bars LIVE from the Exness server at every 5m decision since 2026-09-25 and stored the last complete bar's close, 15m log return and 96-bar z-score (${P.records} records, ${P.first} → ${P.last}; FORWARD_LIVE and BACKFILL provenance; STALE records excluded). V7 recomputed the same three values from the historical 15m files at the same bar times.\n\n| Symbol | Live records | Live STALE (excluded) | Comparable (bar in file, ≥ 100 bars history) | Close match (1e-6) | 15m return match (1e-4) | z-score match (0.05) | z abs diff median / p95 | PASS (≥ 95 %) |\n|---|---|---|---|---|---|---|---|---|\n${Object.entries(P.by_symbol).map(([s, v]) => `| ${s} | ${v.live_records} | ${v.live_stale} | ${v.comparable} | ${pc(v.close_match_rate)} | ${pc(v.ret_match_rate)} | ${pc(v.z_match_rate)} | ${f(v.z_abs_diff_median)} / ${f(v.z_abs_diff_p95)} | ${v.pass ? 'PASS' : 'FAIL'} |`).join('\n')}\n\nThe 2 % non-matches are bars whose close differs by more than 1e-6 between the live snapshot and the file (late broker revisions of the last completed bar); they are reported, not corrected. The z-score formula was aligned to src/shadow/core.js (trailing 96 returns before the last, population standard deviation); with the formula aligned, the match rate is 98 % — the historical file and the live feed are the same data. LIVE_REPLAY_PARITY = ${DEC.live_replay_parity} for the three cross-asset sources. No V7 runtime exists, so decision-level parity (WAIT/PASS) was not exercised live; the feature inputs are proven equivalent.\n`);
W('FORWARD_ONLY_CANDIDATES.md', `# FORWARD-ONLY CANDIDATES (potentially valuable sources without a sufficient historical dataset; no backfill was manufactured; nothing is called proven)\n\n| Candidate | Source | Cost | Availability | Latency | Feature | Future validation plan |\n|---|---|---|---|---|---|---|\n| Order-book imbalance | MT5 \`market_book_get\` on XAUUSDm (Exness) | none | live only; CFD depth is broker-synthetic | per tick | bid/ask volume imbalance at the decision time, depth withdrawal before the decision | add a read-only depth snapshot per 5m decision to the shadow observer (FORWARD_LIVE only), store raw snapshots, pre-register a single rule, measure ≥ 6 months before any claim |\n| Execution latency / slippage state | executor audit log of real fills (only when REAL trades occur) | none | sparse (REAL rarely executes) | — | fill delay, slippage vs quote | collect from DEMO actual orders if a DEMO stage is ever authorised |\n| Silver confirmation (forward measurement) | XAGUSDm live bars (already observed by SC1_SILVER_LEAD_v1) | none | now | 0 | silver_mom6 agreement at production signals | the observer already records silver per decision; pre-register the N2 rule as a MEASURE_ONLY candidate (SC3) and evaluate on ≥ 300 forward production signals before reconsidering |\n\nFORWARD_ONLY_CANDIDATES = 2 (depth imbalance; execution state) plus the forward measurement of the silver rule.\n`);
W('PRACTICALITY_ANALYSIS.md', `# PRACTICALITY ANALYSIS\n\n| Source | Statistical result (HOLD) | Data cost | Fragility | Practical verdict |\n|---|---|---|---|---|\n| Silver (XAGUSDm 5m) | +0.085 R over CONTROL, CI through zero, stress-negative, sign flips with one bar of lag | free, already read live | high (lag-sensitive, SELL-driven, SENSITIVE threshold) | not deployable; forward-measure only |\n| Dollar index (DXYm) | no value | free | — | reject |\n| Nasdaq (USTECm 15m) | negative | free | — | reject |\n| Tick activity | no value | free | — | reject |\n| Release reaction | no value | free | — | reject (News V2 keeps the safety role) |\n| Broker spread state | +0.009 R (3 % of signals) | free | — | execution guard only (production already has a 0.60 USD spread gate) |\n| Depth / order flow | not testable | free live, no history | unknown | forward-only |\n| Exchange volume / yields / sentiment | not available | paid | — | not pursued |\n\nA tiny statistical improvement that depends on zero-lag ingestion of a second instrument does not justify a runtime change; the cheapest next step (forward measurement in the existing observer) costs nothing.\n`);
W('CONTROL_VS_V7.md', `# CONTROL vs V7 (HOLDOUT, sequential, control exit, NORMAL costs)\n\n| Metric | CONTROL | ${BEST} (best V7, source ${srcOf(BEST)}) |\n|---|---|---|\n${[['Trades', (v) => v.n], ['WAIT share', (v) => pc(v.wait_share)], ['Expectancy (R)', (v) => f(v.expectancy_r)], ['PF', (v) => f(v.pf, 2)], ['Max DD (R / USD @0.01)', (v) => `${f(v.max_dd_r, 1)} / ${f(v.max_dd_usd, 0)}`], ['Trade 95 % CI', (v) => ci(v.ci95_r)], ['Block 95 % CI', (v) => ci(v.block_ci95_r)], ['Stress exp (R)', (v) => f(v.stress?.expectancy_r)], ['Wrong-direction (trade / events)', (v) => `${pc(v.wrong_direction_rate)} / ${pc(v.move_capture?.wrong_direction_rate)}`], ['Bad-entry', (v) => pc(v.bad_entry_rate)], ['Move capture', (v) => pc(v.move_capture?.capture_rate)], ['Quarters > 0', (v) => pc(v.quarters_positive_share)], ['Win rate / avg win / avg loss', (v) => `${pc(v.win_rate)} / ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)}`], ['Trades per session (median)', (v) => f(v.trades_per_session?.median)]].map(([k, g]) => `| ${k} | ${g(HC)} | ${g(HB)} |`).join('\n')}\n| DEV exp (R) | ${f(DC.expectancy_r)} | ${f(DB.expectancy_r)} |\n| One-bar-lag exp (R) | — | ${f(R.delay[BEST].delayed_expectancy_r)} |\n\nV7 vs CONTROL: the silver rule is the first layer in seven stages whose improvement has the same sign and comparable size on DEV and HOLD, and it still does not make the stream profitable with confidence. Removing the rule returns CONTROL exactly (ABLATION_RESULTS.md).\n`);
W('INFORMATION_EDGE_V7_SPEC.md', `# INFORMATION EDGE V7 — IMPLEMENTATION SPEC (NOT IMPLEMENTED: no candidate passed; kept so a future passing new-information rule can be ported deterministically)\n\n1. Ingestion: per 5m cycle, read the last COMPLETE bars of the external symbol(s) from the same broker server through the existing read-only reader (as the shadow observer does); persist the raw bar used for every decision.\n2. Freshness: bar complete (open + tf ≤ decision) and not stale (≤ 2 × tf); otherwise feature = NA and the layer passes through (never substitutes).\n3. Feature: pure function of the raw bars (e.g. silver_mom6 = 6-bar close change ÷ silver ATR14); thresholds frozen; computed once per completed candle.\n4. Decision: WAIT only, after the production signal and before the executor; log raw values, feature, threshold, decision.\n5. Lag robustness: the rule must have passed the one-bar-delay test before wiring (the silver rule did not).\n6. Safety unchanged: News V2, spread, drift, breakers, identity, dedup, one position, MARGIN_SAFETY_VETO, broker SL 1.5×; RR 1.70; lot 0.01; Capital Harvest OFF.\n7. Parity fixtures: ≥ 200 live decisions with recorded raw bars → identical features and WAIT decisions in replay (the input-level parity is already shown at 98 %).\n8. Rollback: single mode flag OFF by default; unwired module; no registry file touched.\n\nStatus: SPEC ONLY. EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; nothing was wired.\n`);
